474	\begin{lemma}[Close strategies have close values; Fact 4.32 in \cite{Natarajan2018NEEXP}]\label{lem:close-strategies-have-close-values}
475		\lean{MIPStarRE.QPBT.abs_value_sub_le_of_areClose}
